class Solution:
    def semiOrderedPermutation(self, nums: List[int]) -> int:
        n = len(nums)
        i, j = nums.index(1), nums.index(n)
        return i + (n - 1 - j) - (1 if i > j else 0)

c.cpp:
class Solution {
public:
    int semiOrderedPermutation(vector<int>& nums) {
        int n = nums.size(), i = 0, j = 0;
        for (int k = 0; k < n; k++) {
            if (nums[k] == 1) i = k;
            if (nums[k] == n) j = k;
        }
        return i + (n - 1 - j) - (i > j ? 1 : 0);
    }
};

